-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- automate_dv.sat; PK DISTRIBUTION_CHANNEL_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [2 col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select DISTRIBUTION_CHANNEL_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     group by DISTRIBUTION_CHANNEL_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select DISTRIBUTION_CHANNEL_HKEY as hkey,
           to_varchar(SUBCHANNELCODE) as SUBCHANNELCODE,
           to_varchar(SUBCHANNELEFFECTIVEDATE) as SUBCHANNELEFFECTIVEDATE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
       and DISTRIBUTION_CHANNEL_HKEY in (select hkey from s1)
    qualify rank() over (partition by DISTRIBUTION_CHANNEL_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_DISTRIBUTION_CHANNEL|' || ((nullif(trim(to_varchar("AGENT_CHANNEL")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("SUB_CHANNEL")), ''))) as SUBCHANNELCODE,
               to_varchar((nullif(trim(to_varchar("SUB_CHANNEL_EFFECTIVE_DATE")), ''))) as SUBCHANNELEFFECTIVEDATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'SUBCHANNELCODE' as column_name, c.hkey, c.SUBCHANNELCODE as sat_value,
           max(iff(equal_null(c.SUBCHANNELCODE, e.SUBCHANNELCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.SUBCHANNELCODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SUBCHANNELCODE
    union all
    select 'SUBCHANNELEFFECTIVEDATE' as column_name, c.hkey, c.SUBCHANNELEFFECTIVEDATE as sat_value,
           max(iff(equal_null(c.SUBCHANNELEFFECTIVEDATE, e.SUBCHANNELEFFECTIVEDATE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.SUBCHANNELEFFECTIVEDATE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SUBCHANNELEFFECTIVEDATE
)
select 'MAXIMUS' as project, 'SAT_CHANNEL_DEFINITION' as satellite, 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
order by record_source, column_name;



