----------------------------------------------------------------------------------------
-- 60. MAXIMUS — SAT_AUG_LNK_ROLE_SURVEYOR [Partner LOB]   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. augmented satellite,
-- automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s): MAXIMUS_pd_prop_sp_pv [4
-- col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_SURVEYOR
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(PERFORMANCEEVALUATIONFORMREFERENCE) as PERFORMANCEEVALUATIONFORMREFERENCE,
           to_varchar(PERFORMANCEEVALUATIONOUTCOME) as PERFORMANCEEVALUATIONOUTCOME,
           to_varchar(REPORTTIMELINESSRATING) as REPORTTIMELINESSRATING,
           to_varchar(SURVEYORTYPE) as SURVEYORTYPE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_SURVEYOR
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("SURVEYOR_PERFORMANCE_EVALUATION_FORM")), ''))) as PERFORMANCEEVALUATIONFORMREFERENCE,
               to_varchar((nullif(trim(to_varchar("SURVEYOR_PERFORMANCE_EVALUATION_REPORT")), ''))) as PERFORMANCEEVALUATIONOUTCOME,
               to_varchar((nullif(trim(to_varchar("TIMELY_SUBMISSION_OF_REPORT")), ''))) as REPORTTIMELINESSRATING,
               to_varchar((nullif(trim(to_varchar("TYPE_OF_SURVEYOR")), ''))) as SURVEYORTYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'PERFORMANCEEVALUATIONFORMREFERENCE' as column_name, c.hkey, c.PERFORMANCEEVALUATIONFORMREFERENCE as sat_value,
           max(iff(equal_null(c.PERFORMANCEEVALUATIONFORMREFERENCE, e.PERFORMANCEEVALUATIONFORMREFERENCE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PERFORMANCEEVALUATIONFORMREFERENCE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PERFORMANCEEVALUATIONFORMREFERENCE
    union all
    select 'PERFORMANCEEVALUATIONOUTCOME' as column_name, c.hkey, c.PERFORMANCEEVALUATIONOUTCOME as sat_value,
           max(iff(equal_null(c.PERFORMANCEEVALUATIONOUTCOME, e.PERFORMANCEEVALUATIONOUTCOME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PERFORMANCEEVALUATIONOUTCOME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PERFORMANCEEVALUATIONOUTCOME
    union all
    select 'REPORTTIMELINESSRATING' as column_name, c.hkey, c.REPORTTIMELINESSRATING as sat_value,
           max(iff(equal_null(c.REPORTTIMELINESSRATING, e.REPORTTIMELINESSRATING), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.REPORTTIMELINESSRATING) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.REPORTTIMELINESSRATING
    union all
    select 'SURVEYORTYPE' as column_name, c.hkey, c.SURVEYORTYPE as sat_value,
           max(iff(equal_null(c.SURVEYORTYPE, e.SURVEYORTYPE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.SURVEYORTYPE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SURVEYORTYPE
)
select 'MAXIMUS' as project, 'SAT_AUG_LNK_ROLE_SURVEYOR' as satellite, 'MAXIMUS_pd_prop_sp_pv' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
order by record_source, column_name;



