----------------------------------------------------------------------------------------
-- 92. MAXIMUS — SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. augmented satellite,
-- automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s): MAXIMUS_pd_prop_sp_pv [5
-- col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(AGREEDREPORTSUBMISSIONTAT) as AGREEDREPORTSUBMISSIONTAT,
           to_varchar(EVIDENCERETENTIONTHREEYEARSINDICATOR) as EVIDENCERETENTIONTHREEYEARSINDICATOR,
           to_varchar(OUTSOURCINGJUSTIFICATION) as OUTSOURCINGJUSTIFICATION,
           to_varchar(TASKALLOCATIONTHRESHOLD) as TASKALLOCATIONTHRESHOLD,
           to_varchar(TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR) as TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("TAT_TO_SUBMIT_REPORT")), ''))) as AGREEDREPORTSUBMISSIONTAT,
               to_varchar((nullif(trim(to_varchar("STORAGE_IS_SERVICE_PROVIDER_READY_TO_STORE_THE_COPY_OF_INVESTIGATION_REPORTS_EVIDENCE_FOR_3_YEARS")), ''))) as EVIDENCERETENTIONTHREEYEARSINDICATOR,
               to_varchar((nullif(trim(to_varchar("WHY_THE_INVESTIGATION_TO_BE_OUTSOURCED_TO_THIS_SERVICE_PROVIDER")), ''))) as OUTSOURCINGJUSTIFICATION,
               to_varchar((nullif(trim(to_varchar("TASK_THRESHOLD")), ''))) as TASKALLOCATIONTHRESHOLD,
               to_varchar((nullif(trim(to_varchar("TRAINING_IS_REQUIRED_TO_BE_GIVEN_TO_THE_EMPLOYEES_OF_THE_SERVICE_PROVIDER")), ''))) as TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'AGREEDREPORTSUBMISSIONTAT' as column_name, c.hkey, c.AGREEDREPORTSUBMISSIONTAT as sat_value,
           max(iff(equal_null(c.AGREEDREPORTSUBMISSIONTAT, e.AGREEDREPORTSUBMISSIONTAT), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.AGREEDREPORTSUBMISSIONTAT) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.AGREEDREPORTSUBMISSIONTAT
    union all
    select 'EVIDENCERETENTIONTHREEYEARSINDICATOR' as column_name, c.hkey, c.EVIDENCERETENTIONTHREEYEARSINDICATOR as sat_value,
           max(iff(equal_null(c.EVIDENCERETENTIONTHREEYEARSINDICATOR, e.EVIDENCERETENTIONTHREEYEARSINDICATOR), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.EVIDENCERETENTIONTHREEYEARSINDICATOR) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.EVIDENCERETENTIONTHREEYEARSINDICATOR
    union all
    select 'OUTSOURCINGJUSTIFICATION' as column_name, c.hkey, c.OUTSOURCINGJUSTIFICATION as sat_value,
           max(iff(equal_null(c.OUTSOURCINGJUSTIFICATION, e.OUTSOURCINGJUSTIFICATION), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.OUTSOURCINGJUSTIFICATION) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.OUTSOURCINGJUSTIFICATION
    union all
    select 'TASKALLOCATIONTHRESHOLD' as column_name, c.hkey, c.TASKALLOCATIONTHRESHOLD as sat_value,
           max(iff(equal_null(c.TASKALLOCATIONTHRESHOLD, e.TASKALLOCATIONTHRESHOLD), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.TASKALLOCATIONTHRESHOLD) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.TASKALLOCATIONTHRESHOLD
    union all
    select 'TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR' as column_name, c.hkey, c.TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR as sat_value,
           max(iff(equal_null(c.TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR, e.TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR
)
select 'MAXIMUS' as project, 'SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS' as satellite, 'MAXIMUS_pd_prop_sp_pv' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
