               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_END_DATE")), ''))) as NEGOTIATIONENDDATE,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_REMARKS")), ''))) as NEGOTIATIONREMARKS,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_START_DATE")), ''))) as NEGOTIATIONSTARTDATE,
               to_varchar((nullif(trim(to_varchar("PACKAGE_ACCEPTANCE_DATE")), ''))) as PACKAGEACCEPTANCEDATE,
               to_varchar((nullif(trim(to_varchar("PACKAGE_TYPE")), ''))) as PACKAGETYPE,
               to_varchar((nullif(trim(to_varchar("STEP_DOWN_APPLICABLE")), ''))) as STEPDOWNAPPLICABLEINDICATOR,
               to_varchar((nullif(trim(to_varchar("SURCHARGE")), ''))) as SURCHARGEPERCENTAGE,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_DOCS")), ''))) as TARIFFDOCUMENTREFERENCE,
               to_varchar((nullif(trim(to_varchar("VIEW_TARIFF_DOCS")), ''))) as TARIFFDOCUMENTSAVAILABLEINDICATOR,
               to_varchar((nullif(trim(to_varchar("STEP_DOWN_OPTION_FOR_ROOM_RENT_REMARKS")), ''))) as TARIFFLINEREMARKS,
               to_varchar((nullif(trim(to_varchar("TARIFF_MASTER_UPLOAD")), ''))) as TARIFFMASTERUPLOADEDINDICATOR,
               to_varchar((nullif(trim(to_varchar("TARIFF_STANDARDIZATION")), ''))) as TARIFFSTANDARDISEDINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
